import itertools
import math


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _read_number(value, name):
    if isinstance(value, bool):
        raise ValueError(name + " must be a finite number")
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError(name + " must be a finite number")
        return value
    raise ValueError(name + " must be a finite number")


def _check_finite(value):
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError("non-finite number in payload")
    elif isinstance(value, list):
        for item in value:
            _check_finite(item)
    elif isinstance(value, dict):
        for v in value.values():
            _check_finite(v)


def _nonempty_str(value, name):
    if not isinstance(value, str):
        raise ValueError(name + " must be a string")
    if value.strip() == "":
        raise ValueError(name + " must be non-empty")
    return value


def _better(a, b):
    """True if solution a is better than b: more value, then fewer bytes, then
    lexicographically smaller sorted (archive, mode) list."""
    va, ba, sa = a
    vb, bb, sb = b
    if va != vb:
        return va > vb
    if ba != bb:
        return ba < bb
    return sa < sb


def transform(payloads, contract):
    if len(payloads) != 1:
        raise ValueError("retention_optimizer expects one payload")
    _check_finite(payloads)
    data = _unwrap(payloads[0])
    if not isinstance(data, dict):
        raise ValueError("retention payload must be an object")
    for field in ("archives", "budget", "minimums"):
        if field not in data:
            raise ValueError("retention payload missing " + field)

    archives = data["archives"]
    if not isinstance(archives, list):
        raise ValueError("archives must be a list")

    budget = _read_number(data["budget"], "budget")
    if budget < 0:
        raise ValueError("budget must be >= 0")

    minimums = data["minimums"]
    if not isinstance(minimums, dict):
        raise ValueError("minimums must be an object")
    min_req = {}
    for cat, req in minimums.items():
        if not isinstance(cat, str) or cat.strip() == "":
            raise ValueError("minimums category must be a non-empty string")
        r = _read_number(req, "minimums value")
        if r < 0:
            raise ValueError("minimums value must be >= 0")
        min_req[cat] = r

    parsed = []
    seen_archives = set()
    for a in archives:
        if not isinstance(a, dict):
            raise ValueError("archive must be an object")
        if "id" not in a:
            raise ValueError("archive missing id")
        aid = _nonempty_str(a["id"], "archive id")
        if aid in seen_archives:
            raise ValueError("duplicate archive id")
        seen_archives.add(aid)
        if "category" not in a:
            raise ValueError("archive missing category")
        cat = _nonempty_str(a["category"], "archive category")
        if "hold" not in a:
            raise ValueError("archive missing hold")
        hold = a["hold"]
        if not isinstance(hold, bool):
            raise ValueError("hold must be a bool")
        if "modes" not in a:
            raise ValueError("archive missing modes")
        modes = a["modes"]
        if not isinstance(modes, list):
            raise ValueError("modes must be a list")
        parsed_modes = []
        seen_modes = set()
        for m in modes:
            if not isinstance(m, dict):
                raise ValueError("mode must be an object")
            if "id" not in m:
                raise ValueError("mode missing id")
            mid = _nonempty_str(m["id"], "mode id")
            if mid in seen_modes:
                raise ValueError("duplicate mode id")
            seen_modes.add(mid)
            if "bytes" not in m or "value" not in m:
                raise ValueError("mode missing bytes/value")
            b = _read_number(m["bytes"], "mode bytes")
            v = _read_number(m["value"], "mode value")
            if b < 0 or v < 0:
                raise ValueError("mode bytes/value must be >= 0")
            parsed_modes.append({"id": mid, "bytes": b, "value": v})
        parsed.append(
            {"id": aid, "category": cat, "hold": hold, "modes": parsed_modes}
        )

    option_lists = []
    for a in parsed:
        opts = list(range(len(a["modes"])))
        if not a["hold"]:
            opts = [None] + opts
        option_lists.append(opts)

    best = None
    for combo in itertools.product(*option_lists):
        total_b = 0
        total_v = 0
        cat_counts = {}
        selected = []
        ok = True
        for a, choice in zip(parsed, combo):
            if choice is None:
                continue
            m = a["modes"][choice]
            total_b += m["bytes"]
            total_v += m["value"]
            cat_counts[a["category"]] = cat_counts.get(a["category"], 0) + 1
            selected.append((a["id"], m["id"]))
        if total_b > budget:
            continue
        for cat, req in min_req.items():
            if cat_counts.get(cat, 0) < req:
                ok = False
                break
        if not ok:
            continue
        selected.sort()
        cand = (total_v, total_b, selected)
        if best is None or _better(cand, best):
            best = cand

    if best is None:
        result = {"feasible": False, "selected": [], "bytes": 0, "value": 0}
    else:
        result = {
            "feasible": True,
            "selected": [
                {"archive": aid, "mode": mid} for aid, mid in best[2]
            ],
            "bytes": best[1],
            "value": best[0],
        }
    return {"name": contract["name"], "result": result}

