def _read_number(value, name):
    if isinstance(value, bool):
        raise ValueError(name + " must be a finite number")
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError(name + " must be a finite number")
        return value
    raise ValueError(name + " must be a finite number")


def _check_finite(value):
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError("non-finite number in payload")
    elif isinstance(value, list):
        for item in value:
            _check_finite(item)
    elif isinstance(value, dict):
        for v in value.values():
            _check_finite(v)


def _nonempty_str(value, name):
    if not isinstance(value, str):
        raise ValueError(name + " must be a string")
    if value.strip() == "":
        raise ValueError(name + " must be non-empty")
    return value


def _specificity(resource, action):
    return sum(1 for c in (resource + action) if c not in "*?[]")


def _policy_decision(resource, action, rules):
    matched = []
    for r in rules:
        if fnmatch.fnmatchcase(resource, r["resource"]) and fnmatch.fnmatchcase(
            action, r["action"]
        ):
            matched.append(r)
    if not matched:
        return "deny", None

    def key(r):
        return (
            -r["priority"],
            -_specificity(r["resource"], r["action"]),
            0 if r["effect"] == "deny" else 1,
            r["id"],
        )

    matched.sort(key=key)
    winner = matched[0]
    return winner["effect"], winner["id"]


def _extract_markers(line):
    req = None
    arch = None
    for tok in line.split():
        if req is None and tok.startswith("request="):
            req = tok[len("request="):]
        if arch is None and tok.startswith("archive="):
            arch = tok[len("archive="):]
        if req is not None and arch is not None:
            break
    return req, arch


def transform(payloads, contract):
    if len(payloads) != 3:
        raise ValueError("retention_audit expects three payloads")
    _check_finite(payloads)

    policy_payload = _unwrap(payloads[0])
    log_result = _unwrap(payloads[1])
    ret_result = _unwrap(payloads[2])

    if not isinstance(policy_payload, dict):
        raise ValueError("policy payload must be an object")
    if not isinstance(log_result, dict):
        raise ValueError("log result must be an object")
    if not isinstance(ret_result, dict):
        raise ValueError("retention result must be an object")

    if "rules" not in policy_payload or "requests" not in policy_payload:
        raise ValueError("policy payload missing rules/requests")
    rules_raw = policy_payload["rules"]
    requests_raw = policy_payload["requests"]
    if not isinstance(rules_raw, list):
        raise ValueError("rules must be a list")
    if not isinstance(requests_raw, list):
        raise ValueError("requests must be a list")

    rules = []
    seen_rule_ids = set()
    for r in rules_raw:
        if not isinstance(r, dict):
            raise ValueError("rule must be an object")
        for f in ("id", "resource", "action", "priority", "effect"):
            if f not in r:
                raise ValueError("rule missing " + f)
        rid = r["id"]
        if not isinstance(rid, str) or rid.strip() == "":
            raise ValueError("rule id must be a non-empty string")
        if rid.strip() in seen_rule_ids:
            raise ValueError("duplicate rule id")
        seen_rule_ids.add(rid.strip())
        resource = _nonempty_str(r["resource"], "rule resource")
        action = _nonempty_str(r["action"], "rule action")
        priority = _read_number(r["priority"], "rule priority")
        effect = r["effect"]
        if effect not in ("allow", "deny"):
            raise ValueError("rule effect must be allow or deny")
        rules.append(
            {
                "id": rid,
                "resource": resource,
                "action": action,
                "priority": priority,
                "effect": effect,
            }
        )

    requests = []
    seen_req_ids = set()
    for q in requests_raw:
        if not isinstance(q, dict):
            raise ValueError("request must be an object")
        for f in ("id", "archive", "resource", "action"):
            if f not in q:
                raise ValueError("request missing " + f)
        qid = q["id"]
        if not isinstance(qid, str) or qid.strip() == "":
            raise ValueError("request id must be a non-empty string")
        if qid in seen_req_ids:
            raise ValueError("duplicate request id")
        seen_req_ids.add(qid)
        archive = _nonempty_str(q["archive"], "request archive")
        resource = _nonempty_str(q["resource"], "request resource").strip()
        action = _nonempty_str(q["action"], "request action").strip()
        requests.append(
            {"id": qid, "archive": archive, "resource": resource, "action": action}
        )

    if "feasible" not in ret_result or "selected" not in ret_result:
        raise ValueError("retention result missing feasible/selected")
    feasible = ret_result["feasible"]
    if not isinstance(feasible, bool):
        raise ValueError("feasible must be a bool")
    selected = ret_result["selected"]
    if not isinstance(selected, list):
        raise ValueError("selected must be a list")
    retained = set()
    for s in selected:
        if not isinstance(s, dict) or "archive" not in s:
            raise ValueError("selected entry must have archive")
        a = s["archive"]
        if not isinstance(a, str):
            raise ValueError("selected archive must be a string")
        retained.add(a)

    if "lines" not in log_result:
        raise ValueError("log result missing lines")
    log_lines = log_result["lines"]
    if not isinstance(log_lines, list):
        raise ValueError("log lines must be a list")

    known = {q["id"]: q for q in requests}
    audit_covered = set()
    for ln in log_lines:
        if not isinstance(ln, str):
            raise ValueError("log line must be a string")
        req_id, arch_id = _extract_markers(ln)
        if req_id is None:
            continue
        if req_id not in known:
            raise ValueError("unknown request marker")
        if req_id in audit_covered:
            raise ValueError("duplicate request marker")
        q = known[req_id]
        if arch_id is None or arch_id != q["archive"]:
            raise ValueError("archive marker conflict")
        audit_covered.add(req_id)

    decisions = []
    allow = 0
    deny = 0
    for q in requests:
        if not feasible:
            effect, reason, rule_id = "deny", "plan", None
        elif q["archive"] not in retained:
            effect, reason, rule_id = "deny", "retention", None
        elif q["id"] not in audit_covered:
            effect, reason, rule_id = "deny", "audit", None
        else:
            effect, rule_id = _policy_decision(q["resource"], q["action"], rules)
            reason = "policy"
        decisions.append(
            {"id": q["id"], "effect": effect, "reason": reason, "rule_id": rule_id}
        )
        if effect == "allow":
            allow += 1
        else:
            deny += 1

    result = {"decisions": decisions, "allow": allow, "deny": deny}
    return {"name": contract["name"], "result": result}

